import Foundation

/// The three sound effects as supplied, embedded so the app needs no resource bundle. They are MP3s;
/// `SoundEffects` decodes them at start-up.
enum SoundData {
    /// buttonsound.mp3: two short ticks, after 0.2 seconds of silence that is trimmed off when loaded.
    static let button = ""

    /// partfinished.mp3: a chime, played when one part of a lesson is done.
    static let partFinished = ""

    /// endsuccess.mp3: a longer phrase, played when a whole lesson is done.
    static let lessonFinished = ""
}
